; print.asm -- chapter 16: a page printed by the BIOS
; generated by gen16.py
        INCLUDE "msx.inc"
        OUTPUT "print.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
; CHGMOD with the colours of FORCLR, BAKCLR and BDRCLR, then a page printed
; by CHPUT: 12 clears it, ESC Y and two bytes move the cursor, 13 and 10 end
; a line, 9 is a tab, 8 a step back, and 7 asks for a beep.
init:   di
        ld sp, SYS_AREA
        ld a, BLACK
        ld (FORCLR), a          ; ink
        ld a, WHITE
        ld (BAKCLR), a          ; paper
        ld a, LIGHT_GREEN
        ld (BDRCLR), a          ; border
        ld a, 1                 ; screen 1: 32 x 24 characters
c0:     call CHGMOD
c1:     ld hl, text
p0:     ld a, (hl)
        or a
        jr z, p3                ; the 0 at the end
p1:     call CHPUT              ; one character, or one control code
p2:     inc hl
        jr p0
p3:     nop
stop:   jr stop
text:   db 12, 27, "Y", 32+2, 32+3, "Printed by CHPUT,", 13, 10
        db "a character at a time.", 27, "Y", 32+6, 32+3, "TAB:", 9, "next stop"
        db 27, "Y", 32+8, 32+3, "BS: abc", 8, 8, "X"
        db 27, "Y", 32+10, 32+0, "A line longer than the "
        db "twenty-nine columns wraps.", 7, 0
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
